# Women for whom the platform would say pregnancy is possible: the answer is recorded, so the non-pregnant rules can run.
REPRO = ("DMV-01", "DMV-03", "DMV-07", "DMV-09", "DMV-13", "DMV-20", "DMV-21", "DMV-29", "DMV-32", "DMV-23", "DMV-24")
for _v in VIGNETTES:
    if _v["id"] in REPRO:
        _v["values"].setdefault("pregnancy_possible", True); _v["values"].setdefault("pregnant", False)
    elif _v["values"].get("sex") == "female" and "pregnant" not in _v["values"] and "pregnancy_possible" not in _v["values"] and _v["id"] not in ("DMV-70", "DMV-71"):
        _v["values"]["pregnancy_possible"] = False      # the platform's answer for a child or an older woman
